// ============================================================================
// DIGITAL CLONE - INTAKE AND TRIAGE - CONFIG
// Everything you might want to change lives in this one node. No environment
// variables, so this runs on n8n Cloud unchanged.
//
// A blank key means that step is SKIPPED, never that the run fails. That is what
// lets the whole pipeline be demonstrated before a single credential exists.
// ============================================================================

// ---------------------------------------------------------------- Safety
// Ships in PREVIEW. Nothing is answered and nothing is queued for rendering
// until you set this to false. Read STOP: preview - nothing queued first.
const DRY_RUN = true;

// ---------------------------------------------------------------- The clone
// Who the clone is. This is prepended to the triage prompt so the model answers
// as a named person with a stated remit, not as a generic assistant.
const CLONE_NAME   = 'Alex Rivera';
const CLONE_ROLE   = 'Founder, replying to inbound enquiries';
const CLONE_SCOPE  = 'pricing, availability, what we do, booking a call';

// ---------------------------------------------------------------- Triage
// The low-latency model. GPT-4o-mini class is the right size here: this
// step is a classifier, not a writer, and latency here is felt by the caller.
const LLM_BASE_URL = 'https://api.openai.com/v1';
const LLM_API_KEY  = '';              // blank -> keyword rules only
const LLM_MODEL    = 'gpt-4o-mini';
const LLM_TIMEOUT_MS = 8000;

// How an enquiry is answered. The triage step picks one of these.
//   text   - a written reply, no synthesis at all
//   voice  - ElevenLabs audio only
//   video  - ElevenLabs audio driving a HeyGen avatar
// Rendering costs money and takes time, so the default is deliberately 'text'
// and an enquiry has to earn its way up to video.
const MODE_FOR = {
  booking:   'video',   // worth a face
  pricing:   'voice',   // worth a voice
  question:  'text',
  complaint: 'text',    // a person answers these, see HANDOFF_INTENTS
  spam:      'none',
};
const DEFAULT_MODE = 'text';

// Anything in this list never gets an automated answer of any kind. It is
// flagged for a human instead. Keep complaints and legal here.
const HANDOFF_INTENTS = ['complaint', 'legal', 'press'];

// Keyword fallback, used when LLM_API_KEY is blank or the call times out.
// First match wins.
const KEYWORD_RULES = [
  { intent: 'booking',   any: ['book', 'call', 'meeting', 'demo', 'schedule', 'calendar'] },
  { intent: 'pricing',   any: ['price', 'pricing', 'cost', 'quote', 'how much', 'budget'] },
  { intent: 'complaint', any: ['complaint', 'refund', 'unhappy', 'terrible', 'lawyer'] },
  { intent: 'spam',      any: ['seo services', 'guest post', 'backlink', 'crypto'] },
];

// ---------------------------------------------------------------- Scheduling
// A booking enquiry gets a slot offered rather than a question asked back.
const BOOKING_URL       = '';         // blank -> the reply says a human will follow up
const OFFICE_HOURS      = { start: 9, end: 17 };   // 24h, clone's local time
const CLONE_TIMEZONE    = 'America/New_York';
// Outside office hours the reply still goes out, it just does not promise
// a same-day call. Nobody is left without an answer because it is 02:00.
const OUT_OF_HOURS_NOTE = 'I will confirm a time in the morning.';

// ---------------------------------------------------------------- Render queue
// Where a voice/video request is handed to workflow 02. This is the production
// webhook URL of 02's "When a render is requested" node.
const RENDER_WEBHOOK_URL = '';        // blank -> queued to the log only, nothing renders

// ---------------------------------------------------------------- Reporting
const REPORT_WEBHOOK_URL = '';        // Slack or Discord incoming webhook, optional

// ============================================================================
return [{ json: {
  DRY_RUN, CLONE_NAME, CLONE_ROLE, CLONE_SCOPE,
  LLM_BASE_URL, LLM_API_KEY, LLM_MODEL, LLM_TIMEOUT_MS,
  MODE_FOR, DEFAULT_MODE, HANDOFF_INTENTS, KEYWORD_RULES,
  BOOKING_URL, OFFICE_HOURS, CLONE_TIMEZONE, OUT_OF_HOURS_NOTE,
  RENDER_WEBHOOK_URL, REPORT_WEBHOOK_URL,
  llm_enabled:      LLM_API_KEY.length > 0,
  render_enabled:   RENDER_WEBHOOK_URL.length > 0,
  booking_enabled:  BOOKING_URL.length > 0,
  report_enabled:   REPORT_WEBHOOK_URL.length > 0,
} }];

// Normalise whatever arrived into one shape, so nothing downstream cares whether
// this came from the email trigger, the webhook or the demo button.
const cfg = $('config').first().json;

const SAMPLE = {
  from: 'jordan.blake@example.com',
  name: 'Jordan Blake',
  subject: 'Can you do a call this week?',
  body: 'Hi - saw your site. Could we book 20 minutes this week to talk pricing? Thanks, Jordan',
};

const src = $input.first().json || {};
const raw = {
  from:    src.from || src.email || src.sender || SAMPLE.from,
  name:    src.name || src.fromName || '',
  subject: src.subject || src.title || SAMPLE.subject,
  body:    src.body || src.text || src.message || src.snippet || SAMPLE.body,
  id:      src.id || src.messageId || src.threadId || `demo-${Date.now()}`,
};

// A name is nice to have, never required. Guessing one from an address is worse
// than not using one at all - "Hi Info" is how an automated reply announces itself.
const guess = raw.name || '';
const text = `${raw.subject}\n\n${raw.body}`.trim();

return [{ json: {
  request_id: raw.id,
  from: raw.from,
  name: guess,
  subject: raw.subject,
  body: raw.body,
  text,
  words: text.split(/\s+/).filter(Boolean).length,
  received_at: new Date().toISOString(),
  usable: text.length > 5 && /@/.test(raw.from),
} }];

// No sender address or no text - there is nothing to answer.
const r = $input.first().json;
return [{ json: { stopped_at: 'unreadable enquiry', reason: `No sender address or no text - there is nothing to answer.`, request: r } }];

// Read the model's answer, and refuse to trust it blindly. A classifier that
// returns something unparseable is a classifier that did not answer - falling
// back to the keyword verdict is correct, inventing an intent is not.
const cfg = $('config').first().json;
const r = $('read the request').first().json;
const res = $input.first().json;

let parsed = null;
try {
  const txt = res?.choices?.[0]?.message?.content ?? '';
  parsed = JSON.parse(txt.replace(/^```json\s*|\s*```$/g, '').trim());
} catch (e) { parsed = null; }

const known = Object.keys(cfg.MODE_FOR);
const ok = parsed && typeof parsed.intent === 'string' && known.includes(parsed.intent);

return [{ json: {
  ...r,
  intent:     ok ? parsed.intent : 'question',
  confidence: ok ? Number(parsed.confidence ?? 0.7) : 0.3,
  reason:     ok ? String(parsed.reason || 'model').slice(0, 200)
                 : 'model returned nothing usable, defaulted to question',
  classifier: ok ? 'llm' : 'llm-failed',
} }];

// The fallback classifier. Runs when there is no LLM key, or when the call failed
// or timed out. It is deliberately simple and deliberately explainable: an intent
// you can point at a matched word for is one you can defend when someone asks why.
const cfg = $('config').first().json;
const r = $('read the request').first().json;
const hay = r.text.toLowerCase();

let intent = 'question';
let matched = null;
for (const rule of cfg.KEYWORD_RULES) {
  const hit = rule.any.find(w => hay.includes(w));
  if (hit) { intent = rule.intent; matched = hit; break; }
}

return [{ json: {
  ...r,
  intent,
  confidence: matched ? 0.6 : 0.3,
  reason: matched ? `keyword "${matched}"` : 'no rule matched, defaulted to question',
  classifier: 'keywords',
} }];

// Turn an intent into a decision: who answers, in what medium, and what the
// reply actually says. This is the node a client edits, so everything it reads
// comes from config rather than from anywhere else.
const cfg = $('config').first().json;
const r = $input.first().json;

const handoff = cfg.HANDOFF_INTENTS.includes(r.intent);
let mode = handoff ? 'none' : (cfg.MODE_FOR[r.intent] || cfg.DEFAULT_MODE);

// Low confidence never buys an expensive medium. If we are not sure what they
// asked, we do not spend a render on answering it - and we do not guess at a
// human handoff either; a written reply is the safe middle.
if (!handoff && r.confidence < 0.5 && mode !== 'text') {
  mode = 'text';
}

// Office hours change what the reply promises, never whether it is sent.
const now = new Date();
const hour = Number(new Intl.DateTimeFormat('en-GB', {
  hour: 'numeric', hour12: false, timeZone: cfg.CLONE_TIMEZONE,
}).format(now));
const in_hours = hour >= cfg.OFFICE_HOURS.start && hour < cfg.OFFICE_HOURS.end;

const greet = r.name ? `Hi ${r.name.split(' ')[0]},` : 'Hi,';
const lines = [greet];
if (handoff) {
  lines.push(`Thanks for writing. This one is going straight to a person on the team rather than to me - you will hear from them directly.`);
} else if (r.intent === 'booking') {
  lines.push(`Happy to find a time.`);
  lines.push(cfg.booking_enabled
    ? `You can grab a slot here: ${cfg.BOOKING_URL}`
    : `Someone will come back with a couple of times that work.`);
  if (!in_hours) lines.push(cfg.OUT_OF_HOURS_NOTE);
} else if (r.intent === 'pricing') {
  lines.push(`Good question - pricing depends on scope, so let me give you the short version and we can go deeper on a call.`);
} else if (r.intent === 'spam') {
  lines.push(``);
} else {
  lines.push(`Thanks for getting in touch - here is the short answer.`);
}
lines.push('', `- ${cfg.CLONE_NAME}`);

const script = lines.filter(l => l !== undefined).join('\n').trim();

return [{ json: {
  ...r,
  mode,
  handoff,
  in_hours,
  script,
  // what workflow 02 needs, if this is going to be rendered
  render_request: {
    request_id: r.request_id,
    mode,
    script,
    reply_to: r.from,
  },
  queued: mode === 'voice' || mode === 'video',
} }];

// A complaint, legal or press enquiry. No automated answer of any kind.
const r = $input.first().json;
return [{ json: { stopped_at: 'handed to a person', reason: `A complaint, legal or press enquiry. No automated answer of any kind.`, request: r } }];

// Answered in writing. No synthesis was needed, so none was paid for.
const r = $input.first().json;
return [{ json: { stopped_at: 'text reply only', reason: `Answered in writing. No synthesis was needed, so none was paid for.`, request: r } }];

// RENDER_WEBHOOK_URL is blank, so nothing was handed to workflow 02.
const r = $input.first().json;
return [{ json: { stopped_at: 'render queue not configured', reason: `RENDER_WEBHOOK_URL is blank, so nothing was handed to workflow 02.`, request: r } }];

// DRY_RUN is true. Open this node to read the whole decision before anything is spent.
const r = $input.first().json;
return [{ json: { stopped_at: 'preview - nothing queued', reason: `DRY_RUN is true. Open this node to read the whole decision before anything is spent.`, request: r } }];

// The node to read after a preview run. It is the whole outcome of the pass in
// one object: what came in, what it was classified as, what would have happened.
const r = $input.first().json;
const cfg = $('config').first().json;
const lines = [
  `Clone intake - ${r.request_id || 'no id'}`,
  `  from       ${r.from || '-'}`,
  `  intent     ${r.intent || '-'} (${r.classifier || '-'}, confidence ${r.confidence ?? '-'})`,
  `  reason     ${r.reason || '-'}`,
  `  mode       ${r.mode || '-'}${r.handoff ? '  [HANDOFF - a person answers]' : ''}`,
  `  queued     ${r.queued ? 'yes' : 'no'}${cfg.DRY_RUN ? '   (DRY_RUN - nothing left the building)' : ''}`,
];
return [{ json: { text: lines.join('\n'), ...r } }];
